insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000401', 'home', 'published', '{"title":"Home","seoTitle":"Ever After Memoir — Wedding content creator","seoDescription":"Wedding content creation, reels and little films by Ever After Memoir. Honest moments, fleeting details and the beautiful in-between.","ms":{"title":"Utama","seoTitle":"Ever After Memoir — Wedding content creator","seoDescription":"Wedding content creator, reels dan video pendek oleh Ever After Memoir. Detik jujur, butiran kecil dan segala yang indah di antaranya."},"sections":[{"key":"hero","type":"hero","visible":true,"layout":"reel","slides":[{"id":"00000000-0000-4000-8000-000000000040","url":"/brand/hero-just-married.mp4","type":"video","alt":"Newlyweds in white, soft light around them","width":720,"height":1280,"poster":"/brand/hero-just-married-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},{"id":"00000000-0000-4000-8000-000000000041","url":"/brand/hero-holding-hands.mp4","type":"video","alt":"The couple’s hands, lace and henna","width":720,"height":1280,"poster":"/brand/hero-holding-hands-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000001","url":"/brand/bride-salam.jpg","type":"image","alt":"Bride smiling as the groom rests his hand on her head after the akad nikah","width":1140,"height":1215,"poster":null,"isSample":false}],"interval":5,"eyebrow":"Wedding content creators","headline":"Your day,\n*as it felt.*","body":"Honest moments, fleeting details, and the beautiful in-between — thoughtfully captured, so you can relive the feeling long after the day has passed.","media":{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},"video":null,"focal":"50% 35%","overlay":0.15,"primary":{"label":"Check your date","href":"/contact#book"},"secondary":{"label":"Watch our reels","href":"#reels"},"showTimecode":false,"ms":{"eyebrow":"Wedding content creator","headline":"Hari anda,\n*seperti yang dirasa.*","body":"Detik yang jujur, butiran yang sekejap, dan segala yang indah di antaranya — dirakam dengan teliti, supaya anda dapat merasainya semula lama selepas hari itu berlalu.","primary.label":"Semak tarikh anda","secondary.label":"Tonton reels kami"}},{"key":"philosophy","type":"philosophy","visible":true,"eyebrow":"What we keep","headline":"Not just how it looked.\n*But how it felt.*","body":"The nervous laughter. The trembling hands. The little glances no one else noticed. We capture the moments that happen between the moments — the ones that make your story entirely yours.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/brand/rings-henna.jpg","type":"image","alt":"The couple’s hands with wedding rings and floral henna","width":1169,"height":1215,"poster":null,"isSample":false},"imageSide":"left","ms":{"eyebrow":"Apa yang kami simpan","headline":"Bukan sekadar rupanya.\n*Tetapi rasanya.*","body":"Tawa yang gugup. Tangan yang menggeletar. Pandangan kecil yang tiada siapa perasan. Kami rakam detik-detik di antara detik — yang menjadikan kisah anda milik anda sepenuhnya."}},{"key":"reels","type":"films","visible":true,"eyebrow":"Reels","headline":"Little films.\n*Lasting feelings.*","body":"Your day unfolds in a thousand little moments. We bring them together in a way that lets you feel it all over again.","film":null,"poster":null,"filmCaption":"","reels":[{"video":{"id":"00000000-0000-4000-8000-000000000042","url":"/brand/just-married.mp4","type":"video","alt":"Bride and groom raise their hands together after the ceremony","width":720,"height":1280,"poster":"/brand/just-married-poster.jpg","isSample":false},"poster":null,"caption":"Just married"},{"video":{"id":"00000000-0000-4000-8000-000000000043","url":"/brand/getting-ready.mp4","type":"video","alt":"Getting ready: shoes, songkok and the bride","width":720,"height":1280,"poster":"/brand/getting-ready-poster.jpg","isSample":false},"poster":null,"caption":"Getting ready"},{"video":{"id":"00000000-0000-4000-8000-000000000044","url":"/brand/bridesmaids.mp4","type":"video","alt":"Bridesmaids in powder blue laughing with the bride","width":720,"height":1280,"poster":"/brand/bridesmaids-poster.jpg","isSample":false},"poster":null,"caption":"The bridesmaids"},{"video":{"id":"00000000-0000-4000-8000-000000000046","url":"/brand/couple-pelamin.mp4","type":"video","alt":"Couple on the pelamin beneath their monogram","width":720,"height":1280,"poster":"/brand/couple-pelamin-poster.jpg","isSample":false},"poster":null,"caption":"On the pelamin"},{"video":{"id":"00000000-0000-4000-8000-000000000047","url":"/brand/cake-cutting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"poster":null,"caption":"Cutting the cake"},{"video":{"id":"00000000-0000-4000-8000-000000000045","url":"/brand/holding-hands-film.mp4","type":"video","alt":"Close-up of the couple holding hands","width":720,"height":1280,"poster":"/brand/holding-hands-film-poster.jpg","isSample":false},"poster":null,"caption":"Hold on a little longer"},{"video":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"poster":null,"caption":"Before the guests arrive"},{"video":{"id":"00000000-0000-4000-8000-000000000050","url":"/brand/venue-vendors.mp4","type":"video","alt":"A garden venue and its vendors","width":720,"height":1280,"poster":"/brand/venue-vendors-poster.jpg","isSample":false},"poster":null,"caption":"The venue & vendors"},{"video":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"poster":null,"caption":"Little details"}],"ms":{"headline":"Video kecil.\n*Rasa yang kekal.*","body":"Hari anda terbentang dalam seribu detik kecil. Kami himpunkan semuanya supaya anda dapat merasainya sekali lagi.","reels.0.caption":"Sah!","reels.1.caption":"Bersiap","reels.2.caption":"Para pengapit","reels.3.caption":"Di pelamin","reels.4.caption":"Potong kek","reels.5.caption":"Genggam lebih lama","reels.6.caption":"Sebelum tetamu tiba","reels.7.caption":"Venue & vendor","reels.8.caption":"Butiran kecil"}},{"key":"featured","type":"featured_stories","visible":true,"eyebrow":"Stories","headline":"Days, *remembered.*","body":"A few wedding stories, told the way they felt.","storyIds":[],"link":{"label":"See every story","href":"/stories"},"ms":{"eyebrow":"Kisah","headline":"Hari yang *dikenang.*","body":"Beberapa kisah perkahwinan, diceritakan seperti yang dirasa.","link.label":"Lihat semua kisah"}},{"key":"break","type":"image_break","visible":true,"media":{"id":"00000000-0000-4000-8000-000000000003","url":"/brand/holding-hands.jpg","type":"image","alt":"Bride and groom in white holding hands, bouquet of pink flowers","width":882,"height":1181,"poster":null,"isSample":false},"focal":"50% 50%","quote":"Hold on\n*a little longer.*","caption":"","ms":{"quote":"Genggam\n*lebih lama.*"}},{"key":"services","type":"services_preview","visible":true,"eyebrow":"What we offer","headline":"Ways we can *tell your day.*","link":{"label":"View services","href":"/services"},"ms":{"eyebrow":"Apa yang kami tawarkan","headline":"Cara kami *menceritakan hari anda.*","link.label":"Lihat servis"}},{"key":"testimonials","type":"testimonials","visible":false,"eyebrow":"Kind words","headline":"From our couples","manifesto":"We believe in unposed laughter, in the hush before the vows, in hands that hold on a little longer. We believe the best part of your day is the part you were too busy living to notice.","ms":{"eyebrow":"Kata-kata mereka","headline":"Daripada pasangan kami","manifesto":"Kami percaya pada tawa yang tidak dibuat-buat, pada sunyi sebelum lafaz akad, pada tangan yang menggenggam sedikit lebih lama. Bahagian terindah hari anda ialah bahagian yang anda terlalu sibuk menjalaninya untuk perasan."}},{"key":"social","type":"social","visible":true,"eyebrow":"Follow along","headline":"@everafter.memoir","body":"Behind the scenes, little reels and the moments in between — on Instagram and TikTok.","ms":{"eyebrow":"Ikuti kami","body":"Di sebalik tabir, reels kecil dan detik-detik di antaranya — di Instagram dan TikTok."}},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"See which dates are still open, then say hello on WhatsApp.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Mari simpan kenangan\n*anda dekat di hati.*","body":"Lihat tarikh yang masih kosong, kemudian sapa kami di WhatsApp.","link.label":"Semak tarikh anda"}}]}'::jsonb, '{"title":"Home","seoTitle":"Ever After Memoir — Wedding content creator","seoDescription":"Wedding content creation, reels and little films by Ever After Memoir. Honest moments, fleeting details and the beautiful in-between.","ms":{"title":"Utama","seoTitle":"Ever After Memoir — Wedding content creator","seoDescription":"Wedding content creator, reels dan video pendek oleh Ever After Memoir. Detik jujur, butiran kecil dan segala yang indah di antaranya."},"sections":[{"key":"hero","type":"hero","visible":true,"layout":"reel","slides":[{"id":"00000000-0000-4000-8000-000000000040","url":"/brand/hero-just-married.mp4","type":"video","alt":"Newlyweds in white, soft light around them","width":720,"height":1280,"poster":"/brand/hero-just-married-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},{"id":"00000000-0000-4000-8000-000000000041","url":"/brand/hero-holding-hands.mp4","type":"video","alt":"The couple’s hands, lace and henna","width":720,"height":1280,"poster":"/brand/hero-holding-hands-poster.jpg","isSample":false},{"id":"00000000-0000-4000-8000-000000000001","url":"/brand/bride-salam.jpg","type":"image","alt":"Bride smiling as the groom rests his hand on her head after the akad nikah","width":1140,"height":1215,"poster":null,"isSample":false}],"interval":5,"eyebrow":"Wedding content creators","headline":"Your day,\n*as it felt.*","body":"Honest moments, fleeting details, and the beautiful in-between — thoughtfully captured, so you can relive the feeling long after the day has passed.","media":{"id":"00000000-0000-4000-8000-000000000016","url":"/brand/bride-window.jpg","type":"image","alt":"Bride in a beaded veil holding orchids, standing by the window light","width":1600,"height":2133,"poster":null,"isSample":false},"video":null,"focal":"50% 35%","overlay":0.15,"primary":{"label":"Check your date","href":"/contact#book"},"secondary":{"label":"Watch our reels","href":"#reels"},"showTimecode":false,"ms":{"eyebrow":"Wedding content creator","headline":"Hari anda,\n*seperti yang dirasa.*","body":"Detik yang jujur, butiran yang sekejap, dan segala yang indah di antaranya — dirakam dengan teliti, supaya anda dapat merasainya semula lama selepas hari itu berlalu.","primary.label":"Semak tarikh anda","secondary.label":"Tonton reels kami"}},{"key":"philosophy","type":"philosophy","visible":true,"eyebrow":"What we keep","headline":"Not just how it looked.\n*But how it felt.*","body":"The nervous laughter. The trembling hands. The little glances no one else noticed. We capture the moments that happen between the moments — the ones that make your story entirely yours.","media":{"id":"00000000-0000-4000-8000-000000000002","url":"/brand/rings-henna.jpg","type":"image","alt":"The couple’s hands with wedding rings and floral henna","width":1169,"height":1215,"poster":null,"isSample":false},"imageSide":"left","ms":{"eyebrow":"Apa yang kami simpan","headline":"Bukan sekadar rupanya.\n*Tetapi rasanya.*","body":"Tawa yang gugup. Tangan yang menggeletar. Pandangan kecil yang tiada siapa perasan. Kami rakam detik-detik di antara detik — yang menjadikan kisah anda milik anda sepenuhnya."}},{"key":"reels","type":"films","visible":true,"eyebrow":"Reels","headline":"Little films.\n*Lasting feelings.*","body":"Your day unfolds in a thousand little moments. We bring them together in a way that lets you feel it all over again.","film":null,"poster":null,"filmCaption":"","reels":[{"video":{"id":"00000000-0000-4000-8000-000000000042","url":"/brand/just-married.mp4","type":"video","alt":"Bride and groom raise their hands together after the ceremony","width":720,"height":1280,"poster":"/brand/just-married-poster.jpg","isSample":false},"poster":null,"caption":"Just married"},{"video":{"id":"00000000-0000-4000-8000-000000000043","url":"/brand/getting-ready.mp4","type":"video","alt":"Getting ready: shoes, songkok and the bride","width":720,"height":1280,"poster":"/brand/getting-ready-poster.jpg","isSample":false},"poster":null,"caption":"Getting ready"},{"video":{"id":"00000000-0000-4000-8000-000000000044","url":"/brand/bridesmaids.mp4","type":"video","alt":"Bridesmaids in powder blue laughing with the bride","width":720,"height":1280,"poster":"/brand/bridesmaids-poster.jpg","isSample":false},"poster":null,"caption":"The bridesmaids"},{"video":{"id":"00000000-0000-4000-8000-000000000046","url":"/brand/couple-pelamin.mp4","type":"video","alt":"Couple on the pelamin beneath their monogram","width":720,"height":1280,"poster":"/brand/couple-pelamin-poster.jpg","isSample":false},"poster":null,"caption":"On the pelamin"},{"video":{"id":"00000000-0000-4000-8000-000000000047","url":"/brand/cake-cutting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"poster":null,"caption":"Cutting the cake"},{"video":{"id":"00000000-0000-4000-8000-000000000045","url":"/brand/holding-hands-film.mp4","type":"video","alt":"Close-up of the couple holding hands","width":720,"height":1280,"poster":"/brand/holding-hands-film-poster.jpg","isSample":false},"poster":null,"caption":"Hold on a little longer"},{"video":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"poster":null,"caption":"Before the guests arrive"},{"video":{"id":"00000000-0000-4000-8000-000000000050","url":"/brand/venue-vendors.mp4","type":"video","alt":"A garden venue and its vendors","width":720,"height":1280,"poster":"/brand/venue-vendors-poster.jpg","isSample":false},"poster":null,"caption":"The venue & vendors"},{"video":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"poster":null,"caption":"Little details"}],"ms":{"headline":"Video kecil.\n*Rasa yang kekal.*","body":"Hari anda terbentang dalam seribu detik kecil. Kami himpunkan semuanya supaya anda dapat merasainya sekali lagi.","reels.0.caption":"Sah!","reels.1.caption":"Bersiap","reels.2.caption":"Para pengapit","reels.3.caption":"Di pelamin","reels.4.caption":"Potong kek","reels.5.caption":"Genggam lebih lama","reels.6.caption":"Sebelum tetamu tiba","reels.7.caption":"Venue & vendor","reels.8.caption":"Butiran kecil"}},{"key":"featured","type":"featured_stories","visible":true,"eyebrow":"Stories","headline":"Days, *remembered.*","body":"A few wedding stories, told the way they felt.","storyIds":[],"link":{"label":"See every story","href":"/stories"},"ms":{"eyebrow":"Kisah","headline":"Hari yang *dikenang.*","body":"Beberapa kisah perkahwinan, diceritakan seperti yang dirasa.","link.label":"Lihat semua kisah"}},{"key":"break","type":"image_break","visible":true,"media":{"id":"00000000-0000-4000-8000-000000000003","url":"/brand/holding-hands.jpg","type":"image","alt":"Bride and groom in white holding hands, bouquet of pink flowers","width":882,"height":1181,"poster":null,"isSample":false},"focal":"50% 50%","quote":"Hold on\n*a little longer.*","caption":"","ms":{"quote":"Genggam\n*lebih lama.*"}},{"key":"services","type":"services_preview","visible":true,"eyebrow":"What we offer","headline":"Ways we can *tell your day.*","link":{"label":"View services","href":"/services"},"ms":{"eyebrow":"Apa yang kami tawarkan","headline":"Cara kami *menceritakan hari anda.*","link.label":"Lihat servis"}},{"key":"testimonials","type":"testimonials","visible":false,"eyebrow":"Kind words","headline":"From our couples","manifesto":"We believe in unposed laughter, in the hush before the vows, in hands that hold on a little longer. We believe the best part of your day is the part you were too busy living to notice.","ms":{"eyebrow":"Kata-kata mereka","headline":"Daripada pasangan kami","manifesto":"Kami percaya pada tawa yang tidak dibuat-buat, pada sunyi sebelum lafaz akad, pada tangan yang menggenggam sedikit lebih lama. Bahagian terindah hari anda ialah bahagian yang anda terlalu sibuk menjalaninya untuk perasan."}},{"key":"social","type":"social","visible":true,"eyebrow":"Follow along","headline":"@everafter.memoir","body":"Behind the scenes, little reels and the moments in between — on Instagram and TikTok.","ms":{"eyebrow":"Ikuti kami","body":"Di sebalik tabir, reels kecil dan detik-detik di antaranya — di Instagram dan TikTok."}},{"key":"cta","type":"cta","visible":true,"headline":"Let''s keep your\n*memories close.*","body":"See which dates are still open, then say hello on WhatsApp.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Mari simpan kenangan\n*anda dekat di hati.*","body":"Lihat tarikh yang masih kosong, kemudian sapa kami di WhatsApp.","link.label":"Semak tarikh anda"}}]}'::jsonb, now(), 0) on conflict (slug) do nothing;
insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000402', 'stories', 'published', '{"title":"Stories","seoTitle":"Stories — Ever After Memoir","seoDescription":"Wedding stories by Ever After Memoir — candid moments, quiet details and little films.","ms":{"title":"Kisah","seoTitle":"Kisah — Ever After Memoir","seoDescription":"Kisah perkahwinan oleh Ever After Memoir — detik spontan, butiran kecil dan video pendek."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Our stories","headline":"Every wedding\n*feels different.*","body":"Some are loud and golden, some are quiet and close. Here are a few, told the way they felt.","media":{"id":"00000000-0000-4000-8000-000000000018","url":"/brand/engagement-sign.jpg","type":"image","alt":"Engagement welcome sign on a wooden easel between vases of flowers","width":1600,"height":2133,"poster":null,"isSample":false},"ms":{"eyebrow":"Kisah kami","headline":"Setiap perkahwinan\n*terasa berbeza.*","body":"Ada yang meriah dan bergemerlapan, ada yang tenang dan intim. Inilah sebahagiannya, diceritakan seperti yang dirasa."}},{"key":"grid","type":"stories_grid","visible":true,"showFilters":true},{"key":"cta","type":"cta","visible":true,"headline":"Your story\n*could be next.*","body":"See which dates are still open.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Kisah anda\n*mungkin seterusnya.*","body":"Lihat tarikh yang masih kosong.","link.label":"Semak tarikh anda"}}]}'::jsonb, '{"title":"Stories","seoTitle":"Stories — Ever After Memoir","seoDescription":"Wedding stories by Ever After Memoir — candid moments, quiet details and little films.","ms":{"title":"Kisah","seoTitle":"Kisah — Ever After Memoir","seoDescription":"Kisah perkahwinan oleh Ever After Memoir — detik spontan, butiran kecil dan video pendek."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side