insert into public.pages (id, slug, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000403', 'services', 'published', '{"title":"Services","seoTitle":"Services — Ever After Memoir","seoDescription":"Wedding content creator (WCC) coverage, highlight films and personalised coverage by Ever After Memoir.","ms":{"title":"Servis","seoTitle":"Servis — Ever After Memoir","seoDescription":"Liputan wedding content creator (WCC), video highlight dan liputan mengikut citarasa oleh Ever After Memoir."},"sections":[{"key":"intro","type":"page_intro","visible":true,"layout":"side","eyebrow":"Services","headline":"Made around\n*your day.*","body":"Every couple remembers different things. Choose what matters most to you, and we will shape the coverage around it.","media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"eyebrow":"Servis","headline":"Dibentuk mengikut\n*hari anda.*","body":"Setiap pasangan mengingati perkara yang berbeza. Pilih apa yang paling penting bagi anda, dan kami akan bentuk liputan di sekelilingnya."}},{"key":"list","type":"services_list","visible":true,"addonsHeadline":"Little extras","footnote":"Every wedding is different, so every quote is too. Pick your date and we will reply with options for your day.","ms":{"addonsHeadline":"Tambahan kecil","footnote":"Setiap majlis berbeza, jadi setiap sebut harga pun berbeza. Pilih tarikh anda dan kami akan balas dengan pilihan untuk hari anda."}},{"key":"cta","type":"cta","visible":true,"headline":"Not sure what\n*you need?*","body":"Tell us about your day and we''ll help you choose.","link":{"label":"Check your date","href":"/contact#book"},"ms":{"headline":"Belum pasti\n*apa yang diperlukan?*","body":"Ceritakan tentang majlis anda dan kami akan bantu anda memilih.","link.label":"Semak tarikh anda"}}]}'::jso