eight":532,"poster":null,"isSample":false},"caption":"","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000045","url":"/brand/holding-hands-film.mp4","type":"video","alt":"Close-up of the couple holding hands","width":720,"height":1280,"poster":"/brand/holding-hands-film-poster.jpg","isSample":false},"caption":"Hold on a little longer.","layout":"offset"},{"media":null,"caption":"The little things","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000010","url":"/brand/rings-detail.jpg","type":"image","alt":"Close-up of the rings and henna","width":423,"height":533,"poster":null,"isSample":false},"caption":"","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000009","url":"/brand/pelamin-laugh.jpg","type":"image","alt":"Groom and bride sharing a laugh on the pelamin","width":424,"height":533,"poster":null,"isSample":false},"caption":"And then, laughter.","layout":"half"}],"seoTitle":"","seoDescription":"","isSample":true,"ms":{"title":"Sunyi Antara Kita","excerpt":"Bunga putih, cahaya lembut dan kucupan di tangan.","description":"Pagi yang tenang dan bilik kecil yang penuh bunga putih. Di antara lafaz akad dan sesi bergambar pertama ada satu detik sunyi — tangan di kepalanya, kucupan di tangannya — dan itulah yang kami mahu simpan.","tags.0":"Akad nikah","tags.1":"Pelamin","gallery.0.caption":"Akad","gallery.1.caption":"Salam.","gallery.3.caption":"Genggam lebih lama.","gallery.4.caption":"Butiran kecil","gallery.6.caption":"Kemudian, gelak tawa."}}'::jsonb, now(), 0) on conflict (id) do nothing;
insert into public.stories (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000101', 'published', '{"title":"A Day to Remember","slug":"a-day-to-remember","excerpt":"Bright walls, white baju and a house full of the people who matter.","description":"Getting ready at home, bridesmaids in powder blue and a family that would not stop laughing. A day that was loud in the best way.","cover":{"id":"00000000-0000-4000-8000-000000000004","url":"/brand/family-portrait.jpg","type":"image","alt":"Family in white baju Melayu and wedding dresses laughing together","width":853,"height":1223,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Akad nikah","At home"],"featured":true,"gallery":[{"media":null,"caption":"Before","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000043","url":"/brand/getting-ready.mp4","type":"video","alt":"Getting ready: shoes, songkok and the bride","width":720,"height":1280,"poster":"/brand/getting-ready-poster.jpg","isSample":false},"caption":"Getting ready.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000005","url":"/brand/bride-smile.jpg","type":"image","alt":"Bride in a tiara and veil smiling","width":462,"height":1089,"poster":null,"isSample":false},"caption":"Ready.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000044","url":"/brand/bridesmaids.mp4","type":"video","alt":"Bridesmaids in powder blue laughing with the bride","width":720,"height":1280,"poster":"/brand/bridesmaids-poster.jpg","isSample":false},"caption":"The bridesmaids.","layout":"offset"},{"media":null,"caption":"Everyone","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000004","url":"/brand/family-portrait.jpg","type":"image","alt":"Family in white baju Melayu and wedding dresses laughing together","width":853,"height":1223,"poster":null,"isSample":false},"caption":"The whole family, finally in one photo.","layout":"offset"},{"media"