insert into public.stories (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000103', 'published', '{"title":"In Red and Bloom","slug":"in-red-and-bloom","excerpt":"Deep red drapes, crystal light and a cake cut together.","description":"A reception dressed in deep red and blush flowers. We started with the empty hall, stayed for the pelamin and left after the last slice of cake.","cover":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Reception","Pelamin"],"featured":true,"gallery":[{"media":null,"caption":"The hall","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"caption":"","layout":"full"},{"media":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","width":720,"height":1280,"poster":"/brand/hall-details-poster.jpg","isSample":false},"caption":"Before the doors opened.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000048","url":"/brand/hall-decor.mp4","type":"video","alt":"The hall before the guests arrive: welcome screen, guestbook and aisle","width":720,"height":1280,"poster":"/brand/hall-decor-poster.jpg","isSample":false},"caption":"","layout":"half"},{"media":null,"caption":"The couple","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000046","url":"/brand/couple-pelamin.mp4","type":"video","alt":"Couple on the pelamin beneath their monogram","width":720,"height":1280,"poster":"/brand/couple-pelamin-poster.jpg","isSample":false},"caption":"On the pelamin.","layout":"half"},{"media":{"id":"00000000-0000-4000-8000-000000000047","url":"/brand/cake-cutting.mp4","type":"video","alt":"Cutting the wedding cake together","width":720,"height":1280,"poster":"/brand/cake-cutting-poster.jpg","isSample":false},"caption":"One slice, together.","layout":"half"}],"seoTitle":"","seoDescription":"","isSample":true,"ms":{"title":"Merah dan Mekar","excerpt":"Langsir merah pekat, cahaya kristal dan kek yang dipotong bersama.","description":"Majlis persandingan berhias merah pekat dan bunga merah jambu. Kami bermula dengan dewan yang masih kosong, kekal di pelamin, dan pulang selepas potongan kek terakhir.","tags.0":"Persandingan","tags.1":"Pelamin","gallery.0.caption":"Dewan","gallery.2.caption":"Sebelum pintu dibuka.","gallery.4.caption":"Pasangan","gallery.5.caption":"Di pelamin.","gallery.6.caption":"Satu potong, bersama."}}'::jsonb, '{"title":"In Red and Bloom","slug":"in-red-and-bloom","excerpt":"Deep red drapes, crystal light and a cake cut together.","description":"A reception dressed in deep red and blush flowers. We started with the empty hall, stayed for the pelamin and left after the last slice of cake.","cover":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"weddingDate":"","venue":"","location":"","tags":["Reception","Pelamin"],"featured":true,"gallery":[{"media":null,"caption":"The hall","layout":"chapter"},{"media":{"id":"00000000-0000-4000-8000-000000000017","url":"/brand/pelamin-decor.jpg","type":"image","alt":"Pelamin with deep red drapes, pink and red flowers and crystal chandeliers","width":1600,"height":2133,"poster":null,"isSample":false},"caption":"","layout":"full"},{"media":{"id":"00000000-0000-4000-8000-000000000049","url":"/brand/hall-details.mp4","type":"video","alt":"Flowers and guests at the reception hall","widt