insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000201', 'published', '{"kind":"service","name":"Wedding Content Creator (WCC)","summary":"Candid moments, behind-the-scenes details and the atmosphere of your celebration — as reels, photos and stories ready to share.","description":"We capture your day as it happens — the getting ready, the in-between, the people around you — as short-form content you can share on the day and keep for years.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000061","url":"/brand/getting-ready-poster.jpg","type":"image","alt":"Groom adjusting his songkok","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"summary":"Detik spontan, di sebalik tabir dan suasana majlis anda — sebagai reels, gambar dan story yang sedia dikongsi.","description":"Kami rakam hari anda seadanya — saat bersiap, detik di antaranya, orang di sekeliling anda — sebagai kandungan pendek yang boleh dikongsi pada hari itu juga dan disimpan bertahun-tahun."}}'::jsonb, '{"kind":"service","name":"Wedding Content Creator (WCC)","summary":"Candid moments, behind-the-scenes details and the atmosphere of your celebration — as reels, photos and stories ready to share.","description":"We capture your day as it happens — the getting ready, the in-between, the people around you — as short-form content you can share on the day and keep for years.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000061","url":"/brand/getting-ready-poster.jpg","type":"image","alt":"Groom adjusting his songkok","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"summary":"Detik spontan, di sebalik tabir dan suasana majlis anda — sebagai reels, gambar dan story yang sedia dikongsi.","description":"Kami rakam hari anda seadanya — saat bersiap, detik di antaranya, orang di sekeliling anda — sebagai kandungan pendek yang boleh dikongsi pada hari itu juga dan disimpan bertahun-tahun."}}'::jsonb, now(), 0) on conflict (id) do nothing;
insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000202', 'published', '{"kind":"service","name":"Wedding Highlight Films","summary":"Short-form storytelling that brings together the emotions, energy and memorable details of the day.","description":"A little film made from the moments that mattered most, so you can feel your day all over again.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Video Highlight Perkahwinan","summary":"Penceritaan ringkas yang menghimpunkan emosi, tenaga dan butiran yang tidak dilupakan pada hari itu.","description":"Video kecil daripada detik-detik paling bermakna, supaya anda dapat merasai hari anda sekali lagi."}}'::jsonb, '{"kind":"service","name":"Wedding Highlight Films","summary":"Short-form storytelling that brings together the emotions, energy and memorable details of the day.","description":"A little film made from the moments that mattered most, so you can feel your day all over again.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000060","url":"/brand/just-married-poster.jpg","type":"image","alt":"Bride and groom raising their hands together","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Video Highlight Perkahwinan","summary":"Penceritaan ringkas yang menghimpunkan emosi, tenaga dan butiran yang tidak dilupakan pada hari itu.","description":"Video kecil daripada detik-detik paling bermakna, supaya anda dapat merasai hari anda sekali lagi."}}'::jsonb, now(), 1) on conflict (id) do nothing;
insert into public.services (id, status, draft, published, published_at, sort_order) values ('00000000-0000-4000-8000-000000000203', 'published', '{"kind":"service","name":"Personalised Coverage","summary":"Tailored content coverage based on each couple''s priorities and wedding plans.","description":"Tell us what matters to you and we will shape the coverage around it — from intimate ceremonies to full celebrations.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000065","url":"/brand/hall-decor-poster.jpg","type":"image","alt":"Reception hall aisle with white flowers","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Liputan Mengikut Citarasa","summary":"Liputan kandungan yang disesuaikan dengan keutamaan dan rancangan majlis setiap pasangan.","description":"Beritahu kami apa yang penting bagi anda dan kami akan bentuk liputan di sekelilingnya — dari majlis kecil hingga sambutan besar."}}'::jsonb, '{"kind":"service","name":"Personalised Coverage","summary":"Tailored content coverage based on each couple''s priorities and wedding plans.","description":"Tell us what matters to you and we will shape the coverage around it — from intimate ceremonies to full celebrations.","deliverables":[],"price":"","showPrice":false,"priceNote":"","featured":false,"media":{"id":"00000000-0000-4000-8000-000000000065","url":"/brand/hall-decor-poster.jpg","type":"image","alt":"Reception hall aisle with white flowers","width":720,"height":1280,"poster":null,"isSample":false},"ms":{"name":"Liputan Mengikut Citarasa","summary":"Liputan kandungan yang disesuaikan dengan keutamaan dan rancangan majlis setiap pasangan.","description":"Beritahu kami apa yang penting bagi anda dan kami akan bentuk liputan di sekelilingnya — dari majlis kecil hingga sambutan besar."}}'::jsonb, now(), 2) on conflict (id) do nothing;
